args.sparql:
SELECT DISTINCT ?mother ?motherLabel WHERE {
  VALUES ?person { <http://dbpedia.org/resource/John_I,_Count_Palatine_of_Simmern> }
  {
    ?person <http://dbpedia.org/property/mother> ?mother .
    FILTER(isIRI(?mother))
  } UNION {
    ?person <http://dbpedia.org/ontology/mother> ?mother .
  } UNION {
    ?person <http://dbpedia.org/ontology/parent> ?mother .
  }
  OPTIONAL { ?mother rdfs:label ?motherLabel FILTER(lang(?motherLabel) = "en") }
}

